message.content:
{
  "calls": [
    {
      "name": "lookup_user",
      "args": {
        "employee_id": "EMP-1003"
      }
    }
  ],
  "reply": "Tôi cần xác nhận thông tin nhân viên EMP-1003. Bạn có thể cung cấp thêm thông tin về thiết bị được cấp không?"
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn kiểm tra Wi-Fi trên laptop nào? Vui lòng cung cấp ID của laptop.",
                "response_type": "text"
            }
        }
    ],
    "reply": "Xin chào, tôi cần biết ID của laptop để kiểm tra Wi-Fi của nó. Bạn có thể cung cấp ID không?"
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn kiểm tra tài khoản nhân viên nào trong nhóm Sales?",
                "response_type": "text"
            }
        }
    ],
    "reply": "Tôi cần thêm thông tin về nhân viên cụ thể bạn muốn kiểm tra tài khoản."
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn xác nhận và tạo ticket cho lỗi VPN của thiết bị LT-204 với mức ưu tiên cao? (Có/Không)",
                "response_type": "yes_no"
            }
        }
    ],
    "reply": "Xin lỗi, tôi cần xác nhận trước khi tạo ticket. Bạn có muốn tạo ticket với lỗi VPN của thiết bị LT-204 với mức ưu tiên cao không?"
}

{
    "calls": [
        {
            "name": "lookup_user",
            "args": {
                "employee_id": "EMP-1007"
            }
        },
        {
            "name": "inspect_device",
            "args": {
                "asset_id": "DT-087",
                "check": "security"
            }
        }
    ],
    "reply": "Đã ghi nhớ yêu cầu tra cứu tài khoản nhân viên EMP-1007 và kiểm tra tình trạng bảo mật của máy DT-087. Tôi sẽ thực hiện các bước theo yêu cầu."
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn kiểm tra email ở môi trường nào? (production/staging)",
                "response_type": "choice",
                "options": ["production","staging"]
            }
        }
    ],
    "reply": "Xin chào, tôi cần thông tin về môi trường mà bạn muốn kiểm tra email. Bạn muốn kiểm tra ở môi trường production hay staging?"
}

{
  "calls": [
    {
      "name": "inspect_device",
      "args": {
        "asset_id": "LT-318",
        "check": "vpn"
      }
    },
    {
      "name": "check_service_status",
      "args": {
        "service": "vpn",
        "environment": "production"
      }
    }
  ],
  "reply": "Tôi sẽ kiểm tra vấn đề với dịch vụ VPN trên máy có mã tài sản LT-318, một máy macOS. Đồng thời, tôi cũng sẽ kiểm tra dịch vụ VPN trong môi trường production."
}
